function sortArray(array):
    // Validate input
    if array is empty or has only one element:
        return array

    // Define recursive quicksort procedure
    function quicksort(subArray, low, high):
        if low < high:
            // Partition the array and get pivot index
            pivotIndex = partition(subArray, low, high)

            // Recursively sort elements before and after partition
            quicksort(subArray, low, pivotIndex - 1)
            quicksort(subArray, pivotIndex + 1, high)

    // Define partitioning procedure
    function partition(subArray, low, high):
        // Select rightmost element as pivot
        pivot = subArray[high]
        i = low - 1  // Index of smaller element

        for j from low to high - 1:
            // Compare current element to pivot
            if subArray[j] <= pivot:
                i = i + 1
                swap(subArray[i], subArray[j])

        // Place pivot in correct position
        swap(subArray[i + 1], subArray[high])
        return i + 1

    // Execute sort on full array
    quicksort(array, 0, length(array) - 1)
    return array

// Helper function for element exchange
function swap(a, b):
    temp = a
    a = b
    b = temp
